// (page-level @graph may already include one; duplicate FAQPage triggers GSC errors)
const hasFaqPage = (sd) => {
  if (!sd) return false;
  if (sd['@type'] === 'FAQPage') return true;
  if (Array.isArray(sd['@graph'])) return sd['@graph'].some(n => n && n['@type'] === 'FAQPage');
  return false;
};
